<script setup>
import { computed, ref } from 'vue';
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import Layout from '@/Layouts/ProviderLayout.vue';
const props = defineProps({service:String,status:String,application:Object});
const titles={spaces:'Landlord / property merchant',haul:'Vehicle owner',raketeer:'Freelance service provider'};
const form=useForm({displayName:props.application?.displayName||usePage().props.auth.user.name,phone:props.application?.phone||'',area:props.application?.area||'',description:props.application?.description||'',documents:[],confirmed:false});
const selectionError=ref('');
const locked=computed(()=>props.status==='approved'||(props.status==='pending'&&!!props.application));
function choose(event){const files=Array.from(event.target.files||[]);selectionError.value='';if(files.length>5||files.some(file=>file.size>5*1024*1024)){selectionError.value='Choose up to five documents, no more than 5 MB each.';event.target.value='';form.documents=[];return;}form.documents=files;}
function submit(){form.post(`/provider-applications/${props.service}`,{forceFormData:true,preserveScroll:true});}
</script>
<template><Layout><Head :title="titles[service]+' application'"/><main id="provider-main" class="provider-onboarding application-page"><Link href="/become-provider" class="text-button">← All provider roles</Link><p class="workspace-kicker">Provider application</p><h1>{{ titles[service] }}</h1><p>Tell us about what you offer. An administrator will review your details and documents before unlocking listing tools for this role.</p>
<div v-if="locked" class="application-state"><span class="availability-tag" :class="status==='approved'?'active':'draft'">{{ status==='approved'?'Approved':'Under review' }}</span><h2>{{ status==='approved'?'Your provider role is ready.':'Your application is with our review team.' }}</h2><p>{{ status==='approved'?'You can now create, edit, and publish listings for this role.':'You can continue browsing Aadi. This page will show the outcome after your application is reviewed.' }}</p><p v-if="application?.reviewNote">{{ application.reviewNote }}</p><Link v-if="status==='approved'" :href="`/my-listings/${service}/new`" class="button primary">Create your listing</Link><Link v-else href="/" class="button">Browse nearby</Link><details v-if="application"><summary>Your submitted details</summary><dl><dt>Display / business name</dt><dd>{{ application.displayName }}</dd><dt>Phone</dt><dd>{{ application.phone }}</dd><dt>Primary area</dt><dd>{{ application.area }}</dd><dt>About your offering</dt><dd>{{ application.description }}</dd></dl><a v-for="doc in application.documents" :key="doc.url" :href="doc.url" class="document-link">Download {{ doc.name }}</a></details></div>
<form v-else @submit.prevent="submit" class="application-form"><div v-if="status==='rejected'" class="role-notice"><strong>Please update your application</strong><p>{{ application?.reviewNote || 'Review your details and supporting documents before submitting again.' }}</p></div><div v-if="status==='pending'&&!application" class="role-notice">Your earlier request needs supporting details. Complete this form so an administrator can review it.</div><div v-if="Object.keys(form.errors).length" class="notice error" role="alert"><p v-for="(error,key) in form.errors" :key="key">{{ error }}</p></div><section class="form-section"><h2>About you and your offering</h2><label>Display / business name<input v-model="form.displayName" required maxlength="255" autocomplete="organization"/></label><div class="field-row"><label>Contact phone<input v-model="form.phone" type="tel" autocomplete="tel" required minlength="7" maxlength="40"/></label><label>Primary city / service area<input v-model="form.area" required maxlength="255" placeholder="e.g. Catbalogan City"/></label></div><label>{{ service==='raketeer'?'Skills and services you offer':'About your properties or rental business' }}<textarea v-model="form.description" rows="5" minlength="20" maxlength="3000" required/></label></section><section class="form-section"><h2>Supporting documents</h2><p>Attach a government ID and relevant proof of ownership, authorization, business registration, or service credentials. These files are private and available only to you and administrators.</p><label>Documents · JPG, PNG, WebP, or PDF<input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" multiple required @change="choose"/></label><p class="muted">Up to 5 files, 5 MB per file. A new submission replaces the previous documents.</p><p v-if="selectionError" class="error" role="alert">{{ selectionError }}</p><ul class="selected-documents"><li v-for="file in form.documents" :key="file.name">{{ file.name }}</li></ul><label class="confirmation"><input v-model="form.confirmed" type="checkbox" required/><span>I confirm these details and documents are accurate and authorize Aadi administrators to review them for this provider application.</span></label><p v-if="form.progress" role="status">Uploading: {{ form.progress.percentage }}%</p><button class="button primary" :disabled="form.processing||!!selectionError">{{ form.processing?'Submitting…':'Submit application' }}</button></section></form></main></Layout></template>
